import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    a, b, c, d = map(int, data)
    from collections import Counter
    cnt = Counter([a, b, c, d])
    freq = sorted(cnt.values(), reverse=True)
    # Only consider patterns that can become a full house with one more card
    if len(freq) == 1:
        # all four same: adding any card gives 5 or 4,1 -> not full house
        print("No")
    elif len(freq) == 2:
        # either 3+1 or 2+2
        if (freq[0] == 3 and freq[1] == 1) or (freq[0] == 2 and freq[1] == 2):
            print("Yes")
        else:
            print("No")
    else:
        # 3 distinct or 4 distinct -> cannot form full house with one card
        print("No")

if __name__ == "__main__":
    solve()
