import sys

def solve() -> None:
    it = iter(sys.stdin.read().split())
    N = int(next(it))
    S = next(it).strip()

    left1 = [0] * N
    for i, ch in enumerate(S):
        if ch == '1':
            left1[i] = left1[i - 1] + 1 if i > 0 else 1

    right2 = [0] * N
    for i in range(N - 1, -1, -1):
        ch = S[i]
        if ch == '2':
            right2[i] = right2[i + 1] + 1 if i + 1 < N else 1

    ans = 1  # at least a single '/'
    for j, ch in enumerate(S):
        if ch != '/':
            continue
        l = left1[j - 1] if j > 0 else 0
        r = right2[j + 1] if j + 1 < N else 0
        base = 1 + l + r
        if base % 2 == 1:
            cand = base
        else:
            cand = 0
            if l > 0:
                cand = max(cand, base - 1)
            if r > 0:
                cand = max(cand, base - 1)
            if cand == 0:
                cand = 1  # only '/'
        if cand > ans:
            ans = cand

    print(ans)

if __name__ == "__main__":
    solve()
